// ============================================================
// Code Node: Code-Normalizar WhatsApp
// Projeto Garcia / construction-science-agents
//
// Objetivo:
// - Normalizar o webhook da Evolution API.
// - Identificar o remetente e a obra.
// - Produzir payload_evidencia_api exatamente no contrato do backend.
// - Preparar somente os dados mínimos para o download posterior da mídia.
//
// Governança:
// - Não executa RPA.
// - Não altera RDO, cronograma, pendências, ações ou compras.
// - Não envia e-mail nem arquivos a terceiros.
// - Não inclui o payload original no corpo enviado à API.
// ============================================================

const inputOriginal = $input.first().json;
const body = inputOriginal.body ?? inputOriginal;

// ============================================================
// 0. Configurações operacionais do piloto
// ============================================================

const TENANT_ID = 'construtora-piloto';
const DEFAULT_OBRA_CODIGO = 'OBRA-CAIO';
const RESTRINGIR_REMETENTES = true;

// Telefones somente com dígitos, DDI e DDD.
const CONTATOS_AUTORIZADOS = {
  'TELEFONE_AUTORIZADO_1': {
    nome: 'CONTATO_AUTORIZADO_1',
    funcao: 'MESTRE_OBRAS',
    email: 'EMAIL_AUTORIZADO_1',
    obra_codigo: 'OBRA-CAIO'
  },
  'TELEFONE_AUTORIZADO_2': {
    nome: 'CONTATO_AUTORIZADO_2',
    funcao: 'Engenheiro',
    email: 'EMAIL_AUTORIZADO_2',
    obra_codigo: 'OBRA-CAIO'
  },
  'TELEFONE_AUTORIZADO_3': {
    nome: 'CONTATO_AUTORIZADO_3',
    funcao: 'Engenheira',
    email: null,
    obra_codigo: 'OBRA-CAIO'
  },
  'TELEFONE_AUTORIZADO_4': {
    nome: 'CONTATO_AUTORIZADO_4',
    funcao: 'GERENTE_OBRA',
    email: 'EMAIL_AUTORIZADO_3',
    obra_codigo: 'OBRA-CAIO'
  }
};
// ============================================================
// 1. Funções utilitárias
// ============================================================

function pick(...values) {
  for (const value of values) {
    if (value !== undefined && value !== null && value !== '') {
      return value;
    }
  }
  return null;
}

function cleanText(value) {
  if (value === undefined || value === null) return '';
  return String(value).replace(/^=/, '').trim();
}

function nullableText(value) {
  const text = cleanText(value);
  return text || null;
}

function onlyDigits(value) {
  const text = cleanText(value);
  if (!text) return null;
  const digits = text.replace(/\D/g, '');
  return digits || null;
}

function phoneFromJid(value) {
  const text = cleanText(value);
  if (!text) return null;

  const localPart = text.split('@')[0].split(':')[0];
  return onlyDigits(localPart);
}

function normalizeObraCodigo(value) {
  const text = cleanText(value).toUpperCase();
  if (!text) return null;

  const match = text.match(/\bOBRA(?:[-_\s][A-Z0-9]+)+\b/);
  if (!match) return null;

  return match[0]
    .replace(/[_\s]+/g, '-')
    .replace(/-+/g, '-');
}

function unwrapMessage(message) {
  let current = message && typeof message === 'object' ? message : {};

  for (let i = 0; i < 4; i += 1) {
    const wrapped =
      current?.ephemeralMessage?.message ??
      current?.viewOnceMessage?.message ??
      current?.viewOnceMessageV2?.message ??
      current?.documentWithCaptionMessage?.message;

    if (!wrapped || typeof wrapped !== 'object') break;
    current = wrapped;
  }

  return current;
}

function normalizeBase64(value) {
  const text = cleanText(value);
  if (!text) return null;

  // Aceita base64 puro ou data URL, mas envia somente o conteúdo base64.
  const marker = ';base64,';
  return text.includes(marker) ? text.split(marker).pop() : text;
}

// ============================================================
// 2. Extração do envelope da Evolution API
// ============================================================

const data = body.data ?? body;
const key = data?.key ?? body?.key ?? {};
const messageObject = unwrapMessage(
  data?.message ?? body?.message ?? {}
);

const messageId = nullableText(
  pick(
    key?.id,
    data?.messageId,
    body?.messageId,
    data?.id,
    body?.id
  )
);

const remoteJid = nullableText(
  pick(
    key?.remoteJid,
    data?.remoteJid,
    body?.remoteJid,
    data?.sender,
    body?.sender,
    data?.from,
    body?.from,
    body?.telefone
  )
);

// Em mensagens com addressingMode="lid", remoteJid contém um identificador
// interno e remoteJidAlt contém o telefone real no formato @s.whatsapp.net.
const remoteJidAlt = nullableText(
  pick(
    key?.remoteJidAlt,
    data?.remoteJidAlt,
    body?.remoteJidAlt,
    key?.remoteJidPn,
    data?.remoteJidPn,
    body?.remoteJidPn
  )
);

const participant = nullableText(
  pick(
    key?.participant,
    data?.participant,
    body?.participant
  )
);

const senderPn = nullableText(
  pick(
    key?.senderPn,
    data?.senderPn,
    body?.senderPn,
    key?.sender_pn,
    data?.sender_pn,
    body?.sender_pn
  )
);

// Em grupo, participant identifica o autor. Em conversa direta com @lid,
// remoteJidAlt deve prevalecer sobre o identificador interno.
const senderCandidate = participant || remoteJid;
const senderJid =
  senderCandidate?.includes('@lid')
    ? (remoteJidAlt || senderPn || senderCandidate)
    : (senderPn || participant || remoteJidAlt || remoteJid);

// Telefone real usado na autorização.
const numeroOrigem =
  phoneFromJid(remoteJidAlt) ||
  phoneFromJid(senderPn) ||
  phoneFromJid(senderJid) ||
  phoneFromJid(participant) ||
  phoneFromJid(remoteJid);

const instance = nullableText(
  pick(
    body?.instance,
    body?.instanceName,
    data?.instance,
    data?.instanceName
  )
);

const event = nullableText(
  pick(
    body?.event,
    inputOriginal?.event
  )
);

const pushName = nullableText(
  pick(
    data?.pushName,
    data?.senderName,
    body?.pushName,
    body?.nome_contato
  )
);

// ============================================================
// 3. Identificação e autorização preliminar
// ============================================================

const contatoAutorizado =
  numeroOrigem && CONTATOS_AUTORIZADOS[numeroOrigem]
    ? CONTATOS_AUTORIZADOS[numeroOrigem]
    : null;

const remetenteAutorizado =
  !RESTRINGIR_REMETENTES || Boolean(contatoAutorizado);

const remetenteNome =
  contatoAutorizado?.nome || pushName || 'Remetente não identificado';

const remetenteFuncao =
  contatoAutorizado?.funcao || 'NAO_AUTORIZADO';

const remetenteEmail =
  contatoAutorizado?.email || null;

// Identificador estável enviado ao backend. O número normalizado é preferido
// porque @lid pode variar e não representa necessariamente o telefone real.

const remetenteIdentificador =
  numeroOrigem ||
  remoteJidAlt ||
  senderJid ||
  participant ||
  remoteJid;

// ============================================================
// 4. Conteúdo textual e mídia
// ============================================================

const imageMessage = messageObject?.imageMessage ?? null;
const documentMessage = messageObject?.documentMessage ?? null;
const audioMessage = messageObject?.audioMessage ?? null;
const videoMessage = messageObject?.videoMessage ?? null;

const texto = nullableText(
  pick(
    messageObject?.conversation,
    messageObject?.extendedTextMessage?.text,
    data?.text,
    typeof body?.message === 'string' ? body.message : null,
    body?.mensagem
  )
);

const legenda = nullableText(
  pick(
    imageMessage?.caption,
    documentMessage?.caption,
    videoMessage?.caption
  )
);

let tipoMensagem = 'texto';
let tipoMidia = null;
let mediaMessage = null;

if (imageMessage) {
  tipoMensagem = 'imagem';
  tipoMidia = 'image';
  mediaMessage = imageMessage;
} else if (documentMessage) {
  tipoMensagem = 'documento';
  tipoMidia = 'document';
  mediaMessage = documentMessage;
} else if (audioMessage) {
  tipoMensagem = 'audio';
  tipoMidia = 'audio';
  mediaMessage = audioMessage;
} else if (videoMessage) {
  // O backend atual não possui normalização específica para vídeo.
  tipoMensagem = 'video';
  tipoMidia = null;
  mediaMessage = videoMessage;
}

const mimeType = nullableText(
  pick(
    mediaMessage?.mimetype,
    mediaMessage?.mimeType,
    data?.mimetype,
    body?.mimetype
  )
);

const nomeArquivoOriginal = nullableText(
  pick(
    documentMessage?.fileName,
    mediaMessage?.fileName,
    data?.fileName,
    body?.fileName
  )
);

const arquivoBase64 = normalizeBase64(
  pick(
    mediaMessage?.base64,
    data?.base64,
    body?.base64
  )
);

// ============================================================
// 5. Obra e decisão de roteamento
// ============================================================

const textoParaObra = [texto, legenda].filter(Boolean).join(' ');
const obraCodigoMensagem = normalizeObraCodigo(textoParaObra);

// Durante o piloto, contatos e mensagens devem convergir para OBRA-CAIO.
const obraCodigo =
  obraCodigoMensagem ||
  contatoAutorizado?.obra_codigo ||
  DEFAULT_OBRA_CODIGO;

let decisaoRoteamento = 'REGISTRAR_EVIDENCIA';
let motivoBloqueio = null;

if (key?.fromMe === true) {
  decisaoRoteamento = 'IGNORAR_MENSAGEM_PROPRIA';
  motivoBloqueio = 'Mensagem enviada pela própria instância do WhatsApp.';
} else if (!remetenteAutorizado) {
  decisaoRoteamento = 'BLOQUEAR_REMETENTE_NAO_AUTORIZADO';
  motivoBloqueio = 'Remetente não consta na lista autorizada do piloto.';
} else if (!messageId) {
  decisaoRoteamento = 'BLOQUEAR_SEM_MESSAGE_ID';
  motivoBloqueio = 'A Evolution API não forneceu um identificador de mensagem.';
} else if (!texto && !legenda && !mediaMessage) {
  decisaoRoteamento = 'BLOQUEAR_CONTEUDO_VAZIO';
  motivoBloqueio = 'A mensagem não contém texto, legenda ou mídia suportada.';
} else if (videoMessage) {
  decisaoRoteamento = 'BLOQUEAR_TIPO_MIDIA_NAO_SUPORTADO';
  motivoBloqueio = 'Vídeo ainda não é suportado pelo endpoint de evidências.';
}

const deveBaixarMidia =
  decisaoRoteamento === 'REGISTRAR_EVIDENCIA' &&
  Boolean(tipoMidia) &&
  !arquivoBase64;

// ============================================================
// 6. Payload exatamente compatível com o backend
// ============================================================

const payloadEvidenciaApi = {
  obra_codigo: obraCodigo,
  remetente_nome: remetenteNome,
  remetente_identificador: remetenteIdentificador,
  remetente_autorizado: remetenteAutorizado,
  chat_id: remoteJid,
  message_id: messageId,
  provider_message_id: messageId,
  texto,
  legenda,
  tipo_midia: tipoMidia,
  mime_type: mimeType,
  nome_arquivo_original: nomeArquivoOriginal,
  arquivo_base64: arquivoBase64,
  metadados: {
    tenant_id: TENANT_ID,
    canal: 'whatsapp',
    provider: 'evolution_api',
    instance,
    event,
    tipo_mensagem: tipoMensagem,
    remetente_funcao: remetenteFuncao,
    remetente_email: remetenteEmail,
    numero_origem: numeroOrigem,
    remote_jid: remoteJid,
    remote_jid_alt: remoteJidAlt,
    participant,
    sender_pn: senderPn,
    normalizador: 'Code-Normalizar WhatsApp',
    versao_normalizador: '008e-whatsapp-evidencias-v3'
  }
};

// ============================================================
// 7. Saída do Code Node
// ============================================================

return [
  {
    json: {
      ok_normalizacao: true,
      decisao_roteamento: decisaoRoteamento,
      motivo_bloqueio: motivoBloqueio,
      remetente_autorizado: remetenteAutorizado,
      deve_baixar_midia: deveBaixarMidia,
      payload_evidencia_api: payloadEvidenciaApi,

      // Usar somente no ramo de download da mídia. Não enviar este objeto
      // para o endpoint registrar-evidencia-whatsapp.
      dados_download_midia: deveBaixarMidia
        ? {
            instance,
            message_id: messageId,
            tipo_midia: tipoMidia,
            mime_type: mimeType,
            nome_arquivo_original: nomeArquivoOriginal,
            media_key: nullableText(mediaMessage?.mediaKey),
            direct_path: nullableText(mediaMessage?.directPath),
            file_length: mediaMessage?.fileLength ?? null
          }
        : null
    }
  }
];

// Entrada atual: resposta do download da Evolution
const respostaDownload = $input.first().json;

const download =
  respostaDownload.body &&
  typeof respostaDownload.body === 'object'
    ? respostaDownload.body
    : respostaDownload;

// Recupera o payload original do normalizador
const normalizacao =
  $('Normalizar WhatsApp').first().json;

const payloadOriginal =
  normalizacao.payload_evidencia_api;

if (!payloadOriginal) {
  throw new Error(
    'payload_evidencia_api não encontrado no Normalizar WhatsApp.'
  );
}

function primeiroTextoValido(...valores) {
  return valores.find(
    valor =>
      typeof valor === 'string' &&
      valor.trim().length > 0
  ) ?? null;
}

// Localiza o Base64 retornado pela Evolution
let arquivoBase64 = primeiroTextoValido(
  download.base64,
  download.message?.base64,
  download.data?.base64,
  download.data?.message?.base64,

  typeof download.data === 'string'
    ? download.data
    : null
);

if (!arquivoBase64) {
  const camposRecebidos =
    Object.keys(download).join(', ') || '(nenhum)';

  throw new Error(
    `Base64 não localizado. Campos recebidos: ${camposRecebidos}.`
  );
}

// Remove eventual prefixo data URL
arquivoBase64 = arquivoBase64
  .trim()
  .replace(/^data:[^;]+;base64,/, '');

const mimeType =
  download.mimetype ??
  download.mimeType ??
  payloadOriginal.mime_type ??
  'application/octet-stream';

const extensoes = {
  'image/jpeg': 'jpg',
  'image/jpg': 'jpg',
  'image/png': 'png',
  'image/webp': 'webp',
  'application/pdf': 'pdf',
  'video/mp4': 'mp4',
  'audio/ogg': 'ogg'
};

const extensao =
  extensoes[mimeType] ?? 'bin';

const nomeArquivo =
  payloadOriginal.nome_arquivo_original ??
  download.fileName ??
  download.filename ??
  `${payloadOriginal.message_id}.${extensao}`;

const payloadComMidia = {
  ...payloadOriginal,

  arquivo_base64: arquivoBase64,
  mime_type: mimeType,
  nome_arquivo_original: nomeArquivo,

  metadados: {
    ...(payloadOriginal.metadados ?? {}),
    midia_baixada_evolution: true,
    tamanho_base64_caracteres: arquivoBase64.length,
    largura_imagem: download.width ?? null,
    altura_imagem: download.height ?? null
  }
};

// O node está configurado como "Run Once for All Items"
return [
  {
    json: {
      ...normalizacao,
      payload_evidencia_api: payloadComMidia
    }
  }
];
